// Retro decorations: Generated by Claude Opus 5.5
import React from 'react';
import { StyleProp, Text, TextStyle, View, ViewStyle, useWindowDimensions } from 'react-native';
import Svg, { Circle, Polygon, Rect } from 'react-native-svg';

const hidden = { accessible: false, importantForAccessibility: 'no-hide-descendants' as const };

// Grid of small dots (top-left of the login screen). Default 56 x 40 like the mockup.
export function DotGrid({
  width = 56,
  height = 40,
  color = '#111111',
  spacing = 8,
  radius = 1.6,
}: { width?: number; height?: number; color?: string; spacing?: number; radius?: number }) {
  const dots = [];
  for (let y = spacing / 2; y < height; y += spacing) {
    for (let x = spacing / 2; x < width; x += spacing) {
      dots.push(<Circle key={`${x}-${y}`} cx={x} cy={y} r={radius} fill={color} />);
    }
  }
  return (
    <View {...hidden}>
      <Svg width={width} height={height}>{dots}</Svg>
    </View>
  );
}

// Orange square with a black square below-left of it (top-right of the login screen).
export function CornerSquares({
  size = 26,
  accent = '#FF5A1F',
  ink = '#111111',
}: { size?: number; accent?: string; ink?: string }) {
  const border = 2;
  return (
    <View {...hidden}>
      <Svg width={size * 2} height={size * 2}>
        <Rect x={size + border / 2} y={border / 2} width={size - border} height={size - border} fill={accent} stroke={ink} strokeWidth={border} />
        <Rect x={0} y={size} width={size} height={size} fill={ink} />
      </Svg>
    </View>
  );
}

// Diagonal black/white hazard stripes pinned to the bottom of the screen.
// Use it as the last child of the screen with position: 'absolute', bottom: 0.
export function StripeBand({
  height = 28,
  ink = '#111111',
  background = '#FFFFFF',
  borderWidth = 3,
  style,
}: { height?: number; ink?: string; background?: string; borderWidth?: number; style?: StyleProp<ViewStyle> }) {
  const { width } = useWindowDimensions();
  const period = 40; // distance between stripes
  const stripe = 20; // stripe thickness, measured horizontally
  const stripes = [];
  for (let x = -height; x < width + period; x += period) {
    // a 45-degree parallelogram
    const points = `${x},${height} ${x + stripe},${height} ${x + stripe + height},0 ${x + height},0`;
    stripes.push(<Polygon key={x} points={points} fill={ink} />);
  }
  return (
    <View {...hidden} style={[{ height: height + borderWidth, borderTopWidth: borderWidth, borderTopColor: ink }, style]}>
      <Svg width={width} height={height}>
        <Rect x={0} y={0} width={width} height={height} fill={background} />
        {stripes}
      </Svg>
    </View>
  );
}

// The hard, offset black shadow behind buttons and cards.
// React Native's built-in shadows are soft (and Android elevation can't do offsets),
// so this draws a solid block behind the child instead.
// The child needs its own backgroundColor so it covers the shadow.
export function HardShadow({
  offset = 5,
  color = '#111111',
  style,
  children,
}: { offset?: number; color?: string; style?: StyleProp<ViewStyle>; children: React.ReactNode }) {
  return (
    <View style={[{ marginRight: offset, marginBottom: offset }, style]}>
      <View
        {...hidden}
        style={{ position: 'absolute', top: offset, left: offset, right: -offset, bottom: -offset, backgroundColor: color }}
      />
      {children}
    </View>
  );
}

// Yellow block behind a headline word, like "BACK!" in "WELCOME BACK!".
export function Highlight({
  children,
  background = '#FFC21A',
  textStyle,
}: { children: React.ReactNode; background?: string; textStyle?: StyleProp<TextStyle> }) {
  return (
    <View style={{ alignSelf: 'flex-start', backgroundColor: background, paddingHorizontal: 10, paddingTop: 4, marginTop: 6 }}>
      <Text style={textStyle}>{children}</Text>
    </View>
  );
}
